def _validate_braces(self):
    """Validate that all parts within a pattern are fully enclosed in matching braces."""
    i = 0
    while i < len(self._format):
        c = self._format[i]
        if c == '\\':
            # Skip escaped character
            i += 2
        elif c == '{':
            if i + 1 < len(self._format) and self._format[i + 1] == '{':
                # Escaped brace - skip both
                i += 2
            else:
                # Opening brace - find matching closing brace
                depth = 1
                i += 1
                while i < len(self._format) and depth > 0:
                    if self._format[i] == '\\':
                        i += 2
                    elif self._format[i] == '{':
                        if i + 1 < len(self._format) and self._format[i + 1] == '{':
                            i += 2
                        else:
                            depth += 1
                            i += 1
                    elif self._format[i] == '}':
                        if i + 1 < len(self._format) and self._format[i + 1] == '}':
                            i += 2
                        else:
                            depth -= 1
                            i += 1
                    else:
                        i += 1
                if depth != 0:
                    raise ValueError("Format string has unbalanced braces: %r" % self._format)
        elif c == '}':
            if i + 1 < len(self._format) and self._format[i + 1] == '}':
                # Escaped brace - skip both
                i += 2
            else:
                # Unmatched closing brace
                raise ValueError("Format string has unbalanced braces: %r" % self._format)
        else:
            i += 1
